# Let me try a different projection hypothesis
# output[r][c] = 8 if input has 8 on diagonal where we project "material" from corners

# Let me look at the output pattern differently
# In Demo 1 output, the 8s form a pattern that can be described as:
# - A "tilted" version of the input box
# - The tilt is such that the box body is "pushed" toward the bottom-left

# What if the rule is about preserving the shape but applying a linear transformation?
# Let me check if output is input shifted by some amount, OR if it's input mirrored

def extended_positions(grid_in):
    """Return extended positions: each position (r,c) maps to (r,c), (r+1,c-1), (r+2,c-2), etc."""
    positions = []
    r_in, c_in = len(grid_in), len(grid_in[0])
    for r, row in enumerate(grid_in):
        for c, val in enumerate(row):
            if val != 0:
                # Add position itself and all positions down-left
                for k in range(r_in):
                    for l in range(c_in):
                        if r-k >= 0 and c+l < c_in and r+l < r_in and c-l >= 0:
                            positions.append((r-k, c+l))
    return positions

# Actually, let me try: output[r][c] = color if input[r + k][c + k] or input[r - k][c - k] matches for some k
# This checks if the cell can be reached by moving "up-right" from some input cell

def check_different_diags(grid_in, grid_out, color=8):
    r_in, c_in = len(grid_in), len(grid_in[0])
    r_out, c_out = len(grid_out), len(grid_out[0])

    matches = []
    mismatches = []

    for r in range(r_out):
        for c in range(c_out):
            target = grid_out[r][c]
            if target == 0:
                # Check if input has color at same position or moving along diagonals...
                # Let's try: target should be 0 unless there's a color cell that projects here
                matches.append(f"({r},{c}): {target}")
                continue

            # If target is color, check if any input cell projects here
            found = False
            for k in range(max(r_in, c_out)):
                # Check up-right diagonal from output: (r-k, c-k)
                if r-k >= 0 and c-k >= 0:
                    if grid_in[r-k][c-k] == color:
                        found = True
                        break
                # Check down-left diagonal from output: (r+k, c+k)
                if r+k < r_in and c+k < c_in:
                    if grid_in[r+k][c+k] == color:
                        found = True
                        break
            if found:
                matches.append(f"({r},{c}): {target} - found via diag")
            else:
                matches.append(f"({r},{c}): {target} - NOT FOUND")

    print("Demo 1 - Primary diagonal projection check:")
    for line in matches[:20]:
        print(line)

check_different_diags(d1_in, d1_out)

# Now let me try yet another hypothesis: 
# What if output is input but we only keep cells that form valid "structures"?
# Like, a cell (r,c) stays as color in output ONLY IF the column also has that color somewhere?

def check_structure_preservation(grid_in, grid_out, color=8):
    """Check if output preserves structure: output[r][c] = color IFF:
    - input[r][c] == color AND 
    - either column c has color elsewhere, OR row r has color elsewhere"""
    r_in, c_in = len(grid_in), len(grid_in[0])

    new_out = [[0]*c_in for _ in range(r_in)]
    # Find which rows/cols have colors
    rows_with_color = set()
    cols_with_color = set()
    for r, row in enumerate(grid_in):
        for c, val in enumerate(row):
            if val == color:
                rows_with_color.add(r)
                cols_with_color.add(c)

    for r in range(r_in):
        for c in range(c_in):
            if grid_in[r][c] == color and (r in rows_with_color and c in cols_with_color):
                new_out[r][c] = color

    return new_out == grid_out

print(f"\nStructure preservation (Baseline): {check_structure_preservation(d1_in, d1_out, color=8)}")

# Let me try a completely different approach
# What if for each non-background cell in input, we project it to multiple positions in output?

def try_multiple_projection(grid_in, grid_out, color=8):
    """Each input cell of color maps to output cells based on position"""
    r_in, c_in = len(grid_in), len(grid_in[0])

    # Track which output cells are set
    proj_count = [[0]*c_in for _ in range(r_in)]

    for r_in in range(r_in):
        for c_in in range(c_in):
            if grid_in[r_in][c_in] == color:
                # This cell contributes to output
                # Try: contribution to output rows r_in+k for various k
                for k in range(r_in):
                    # Horizontal projection at row r_in+k
                    # Where to project horizontally? Based on original column?
                    proj_count[r_in + k][c_in] += 1  # Keep same column

    # Check comparison
    r_out = len(grid_out)
    for r in range(r_out):
        for c in range(len(grid_out[0])):
            expected = color if grid_out[r][c] == color else 0
            matches = proj_count[r][c] == expected
            if not matches:
                print(f"Mismatch at ({r},{c}): expected {expected}, got {proj_count[r][c]}")
                return False
    return True

# Hmm that's too simple. Let me try another approach:
# What if each input cell at (r_in, c_in) maps to output cells at positions where
# the cell would be "visible" from that input cell in some projection direction?

def try_visibility_projection(grid_in, grid_out, color=8):
    """Output cell is colored if it doesn't 'block' some input cell's view"""
    r_in, c_in = len(grid_in), len(grid_in[0])

    proj = [[0]*c_in for _ in range(r_in)]

    for r_in in range(r_in):
        for c_in in range(c_in):
            if grid_in[r_in][c_in] == color:
                # This cell projects along its row and column
                # Row projection: mark all cells in same row as "lit"
                for c in range(c_in):
                    proj[r_in][c] = color
                # Col projection: mark all cells in same column
                for r in range(r_in):
                    proj[r][c_in] = color

    return proj == grid_out

# No, that would make entire rows and columns colored, which is wrong.

# Let me try: what if the output is based on "diagonal visibility"?
# An output cell (r,c) is colored if some input cell can "see" it diagonally
# without blocked by blocking cells?

def try_diag_visibility(grid_in, grid_out, color=8):
    """Output cell colored if no input cell blocks diagonal view from some source"""
    r_in, c_in = len(grid_in), len(grid_in[0])

    # For each potential source, see what it illuminates
    proj = [[0]*c_in for _ in range(r_in)]

    for r_src in range(r_in):
        for c_src in range(c_in):
            if grid_in[r_src][c_src] == color:
                # Project diagonal paths up-right and down-left
                # Check if this path is unblocked to certain cells

                # Path up-right: (r_src-k, c_src+k) for k=1,2,...
                for k in range(1, r_in):
                    r_dst, c_dst = r_src - k, c_src + k
                    if 0 <= r_dst < r_in and 0 <= c_dst < c_in:
                        # Path is open if all intermediate cells don't block
                        blocked = False
                        for i in range(1, k):
                            if grid_in[r_src - i][c_src + i] == color and c_src + i != c_dst:
                                blocked = True
                                break

                        proj[r_dst][c_dst] = color if not blocked else 0
                        print(f"Source ({r_src},{c_src}) -> ({r_dst},{c_dst}): visible={not blocked}")

    return proj == grid_out

result = try_diag_visibility(d1_in, d1_out, color=8)
print(f"Diagonal visibility matches: {result}")

print("\n\nLet me analyze the differences between input and output more systematically")
diff_positions = []
for r in range(min(len(d1_in), len(d1_out))):
    for c in range(min(len(d1_in[0]), len(d1_out[0]))):
        if d1_in[r][c] != d1_out[r][c]:
            diff_positions.append(((r,c), d1_in[r][c], d1_out[r][c]))
print(f"Different positions: {len(diff_positions)}")
for i in range(min(10, len(diff_positions))):
    print(f"  {diff_positions[i]}")

